import React, { useEffect, useRef, useState, useCallback } from "react";
import Avatar from "./Avatar";
import { useAuth } from "../context/AuthContext";
import { getRoomName, fmtTime, fmtDate, fmtLastSeen } from "../utils/helpers";
import { getChatHistory, getUserStatus } from "../services/api";
import { wsService } from "../services/websocket";

const EMOJI_LIST = ["👍","❤️","😂","😮","😢","🔥","🎉","💯"];
const TYPING_TIMEOUT = 2500;

export default function ChatWindow({ room, messages, onNewMessage, wsConnected, onBack }) {
  const { username } = useAuth();
  const [text, setText]       = useState("");
  const [loading, setLoading] = useState(false);
  const [fetched, setFetched] = useState(false);
  const [typingUsers, setTypingUsers] = useState([]);
  const [peerStatus, setPeerStatus]   = useState(null);

  const bottomRef    = useRef(null);
  const inputRef     = useRef(null);
  const containerRef = useRef(null);
  const typingTimer  = useRef(null);
  const isTyping     = useRef(false);

  const isGroup  = room?.isGroup || room?.group;
  const roomName = room ? getRoomName(room, username) : "";

  // Fetch history
  useEffect(() => {
    if (!room) return;
    setFetched(false); setLoading(true); setTypingUsers([]);
    getChatHistory(room.id)
      .then(({ data }) => { onNewMessage(room.id, data, true); setFetched(true); })
      .catch(() => setFetched(true))
      .finally(() => setLoading(false));
  }, [room?.id]);

  // Subscribe messages + typing
  useEffect(() => {
    if (!room) return;
    wsService.subscribeRoom(room.id, (msg) => onNewMessage(room.id, [msg], false));
    wsService.subscribeTyping(room.id, (ev) => {
      if (ev.username === username) return;
      setTypingUsers((p) => {
        const next = ev.typing ? (p.includes(ev.username) ? p : [...p, ev.username]) : p.filter(u => u !== ev.username);
        return next;
      });
      setTimeout(() => setTypingUsers((p) => p.filter(u => u !== ev.username)), 4000);
    });
  }, [room?.id, wsConnected]);

  // Peer status + last seen polling
  useEffect(() => {
    if (!room || isGroup) return;
    const peer = (room.participantIds || []).find(u => u !== username);
    if (!peer) return;
    setPeerStatus(null);
    getUserStatus(peer).then(({ data }) => setPeerStatus(data)).catch(() => {});
    const iv = setInterval(() => getUserStatus(peer).then(({ data }) => setPeerStatus(data)).catch(() => {}), 30000);
    return () => clearInterval(iv);
  }, [room?.id, isGroup]);

  // Scroll to bottom
  useEffect(() => {
    setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: "smooth" }), 60);
  }, [messages?.length, typingUsers.length]);

  // Mobile: scroll to bottom when keyboard opens
  useEffect(() => {
    const handler = () => {
      setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: "instant" }), 300);
    };
    window.visualViewport?.addEventListener("resize", handler);
    return () => window.visualViewport?.removeEventListener("resize", handler);
  }, []);

  const stopTyping = useCallback(() => {
    clearTimeout(typingTimer.current);
    if (isTyping.current && room) {
      isTyping.current = false;
      wsService.sendTyping(room.id, username, false);
    }
  }, [room, username]);

  const handleTextChange = (e) => {
    setText(e.target.value);
    e.target.style.height = "auto";
    e.target.style.height = Math.min(e.target.scrollHeight, 120) + "px";
    if (!wsService.connected || !room) return;
    if (!isTyping.current) { isTyping.current = true; wsService.sendTyping(room.id, username, true); }
    clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => {
      isTyping.current = false;
      wsService.sendTyping(room.id, username, false);
    }, TYPING_TIMEOUT);
  };

  const send = useCallback(() => {
    const content = text.trim();
    if (!content || !room || !wsService.connected) return;
    stopTyping();
    wsService.sendMessage(room.id, content, username, username);
    setText("");
    if (inputRef.current) { inputRef.current.style.height = "auto"; inputRef.current.focus(); }
  }, [text, room, username, stopTyping]);

  const handleKey = (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } };

  if (!room) return <EmptyState />;

  const grouped = groupByDate(messages || []);
  const isOnline = !isGroup && peerStatus?.status === "ONLINE";
  const headerSub = isGroup
    ? `${(room.participantIds || []).length} members`
    : peerStatus ? fmtLastSeen(peerStatus.status, peerStatus.lastSeen) : "…";

  return (
    <div className="flex flex-col h-full bg-crisp-bg" style={{ height: "100%" }}>

      {/* ── Header ──────────────────────────────────────────────────────── */}
      <div className="flex items-center gap-3 px-4 py-3 bg-crisp-surface border-b border-crisp-border
        flex-shrink-0 pt-safe">
        {/* Back button — mobile only */}
        {onBack && (
          <button onClick={onBack}
            className="w-9 h-9 rounded-xl flex items-center justify-center text-crisp-sub
              hover:bg-crisp-card active:scale-95 transition-all flex-shrink-0 -ml-1 sm:hidden">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path d="M19 12H5M12 5l-7 7 7 7"/>
            </svg>
          </button>
        )}
        <div className="relative flex-shrink-0">
          <Avatar name={roomName} size="md" square={isGroup} />
          {isOnline && <span className="absolute bottom-0 right-0 w-3 h-3 bg-crisp-green rounded-full border-2 border-crisp-surface" />}
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-bold text-[15px] text-crisp-text truncate leading-tight">{roomName}</div>
          <div className={`text-[11px] font-mono mt-0.5 truncate transition-colors
            ${isOnline ? "text-crisp-green" : "text-crisp-muted"}`}>
            {typingUsers.length > 0
              ? <span className="text-crisp-accent2 animate-pulse2">typing…</span>
              : headerSub}
          </div>
        </div>
        {/* Connection pill */}
        <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl border text-[11px] font-mono flex-shrink-0
          ${wsConnected ? "bg-crisp-card border-crisp-border text-crisp-muted" : "bg-red-500/10 border-red-500/20 text-red-400"}`}>
          <span className={`w-1.5 h-1.5 rounded-full ${wsConnected ? "bg-crisp-green" : "bg-red-400 animate-pulse2"}`} />
          {wsConnected ? "Live" : "…"}
        </div>
      </div>

      {/* ── Messages ────────────────────────────────────────────────────── */}
      <div ref={containerRef} className="flex-1 overflow-y-auto px-3 py-3 no-scrollbar"
        style={{ overscrollBehavior: "contain" }}>
        {loading && <LoadingDots />}

        {!loading && fetched && (!messages || messages.length === 0) && (
          <div className="flex flex-col items-center justify-center h-full gap-3 py-16">
            <div className="text-4xl opacity-25">💬</div>
            <p className="text-crisp-muted text-sm font-body text-center">
              No messages yet<br/>Say hello!
            </p>
          </div>
        )}

        {grouped.map(({ date, msgs }) => (
          <div key={date}>
            <DateDivider label={date} />
            {msgs.map((msg, i) => (
              <MessageBubble
                key={msg.id || `${msg.roomId}-${i}`}
                msg={msg}
                isOwn={msg.senderId === username}
                showSender={isGroup && msg.senderId !== username}
                prevMsg={i > 0 ? msgs[i - 1] : null}
                currentUser={username}
                roomId={room.id}
              />
            ))}
          </div>
        ))}

        {typingUsers.length > 0 && <TypingIndicator users={typingUsers} />}
        <div ref={bottomRef} className="h-2" />
      </div>

      {/* ── Input area ──────────────────────────────────────────────────── */}
      <div className="flex-shrink-0 bg-crisp-surface border-t border-crisp-border pb-safe">
        <div className="flex items-end gap-2 px-3 py-3">
          <div className="flex-1 flex items-end bg-crisp-card border border-crisp-border2
            rounded-3xl px-4 py-2.5 focus-within:border-crisp-accent/60 transition-all duration-200
            focus-within:shadow-accent-sm min-h-[48px]">
            <textarea
              ref={inputRef}
              className="flex-1 bg-transparent text-crisp-text font-body outline-none
                resize-none placeholder:text-crisp-muted leading-relaxed no-scrollbar self-center"
              style={{ fontSize: "16px", maxHeight: "120px", paddingTop: "2px", paddingBottom: "2px" }}
              placeholder={wsConnected ? `Message ${roomName}…` : "Connecting…"}
              rows={1}
              value={text}
              onChange={handleTextChange}
              onKeyDown={handleKey}
              onBlur={stopTyping}
            />
          </div>
          <button onClick={send} disabled={!text.trim() || !wsConnected}
            className="w-12 h-12 bg-crisp-accent hover:bg-crisp-accentDk disabled:opacity-30
              disabled:cursor-not-allowed rounded-full flex items-center justify-center flex-shrink-0
              transition-all duration-200 active:scale-90 shadow-accent-sm">
            <SendIcon />
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Typing indicator ──────────────────────────────────────────────────────────
function TypingIndicator({ users }) {
  return (
    <div className="flex items-center gap-2 mt-2 mb-1 animate-fadeIn px-2">
      <div className="flex gap-1 items-center px-3 py-2 bg-crisp-card border border-crisp-border
        rounded-2xl rounded-bl-md w-fit">
        {[0,1,2].map(i => (
          <span key={i} className="w-1.5 h-1.5 rounded-full bg-crisp-muted animate-pulse2"
            style={{ animationDelay: `${i * 0.18}s` }} />
        ))}
      </div>
      <span className="text-[11px] text-crisp-muted font-mono italic">
        {users[0]}{users.length > 1 ? ` +${users.length - 1}` : ""} typing…
      </span>
    </div>
  );
}

// ── Message bubble with reactions ─────────────────────────────────────────────
function MessageBubble({ msg, isOwn, showSender, prevMsg, currentUser, roomId }) {
  const sameAuthor = prevMsg?.senderId === msg.senderId;
  const gap        = sameAuthor ? "mt-0.5" : "mt-3";
  const [showPicker, setShowPicker] = useState(false);
  const pickerRef = useRef(null);

  useEffect(() => {
    if (!showPicker) return;
    const h = (e) => { if (pickerRef.current && !pickerRef.current.contains(e.target)) setShowPicker(false); };
    document.addEventListener("pointerdown", h);
    return () => document.removeEventListener("pointerdown", h);
  }, [showPicker]);

  const react = (emoji) => { wsService.sendReaction(msg.id, roomId, emoji); setShowPicker(false); };
  const reactions = msg.reactions || {};
  const hasReactions = Object.keys(reactions).some(k => reactions[k]?.length > 0);

  return (
    <div className={`flex ${isOwn ? "flex-row-reverse" : "flex-row"} items-end gap-2 ${gap} group`}>
      {/* Avatar */}
      <div className="w-8 flex-shrink-0 self-end">
        {!isOwn && !sameAuthor && <Avatar name={msg.senderName || msg.senderId} size="xs" />}
      </div>

      <div className={`flex flex-col max-w-[78%] sm:max-w-[68%] ${isOwn ? "items-end" : "items-start"}`}>
        {showSender && !sameAuthor && (
          <span className="text-[11px] text-crisp-muted font-display font-semibold mb-1 px-1">
            {msg.senderName || msg.senderId}
          </span>
        )}

        {/* Bubble + reaction button row */}
        <div className={`flex items-end gap-1.5 ${isOwn ? "flex-row-reverse" : "flex-row"} relative`}
          ref={pickerRef}>
          <div className={`${isOwn ? "animate-msgInR bubble-own" : "animate-msgInL bubble-them"}`}>
            {msg.content}
          </div>

          {/* React button — shown on hover desktop, tap on mobile */}
          {msg.id && (
            <button
              onClick={() => setShowPicker(p => !p)}
              className="opacity-0 group-hover:opacity-100 sm:opacity-0 sm:group-hover:opacity-100
                w-7 h-7 rounded-full bg-crisp-card border border-crisp-border
                flex items-center justify-center text-sm
                transition-all hover:bg-crisp-hover active:scale-90 flex-shrink-0 mb-1"
              style={{ fontSize: "14px" }}>
              😊
            </button>
          )}

          {/* Emoji picker */}
          {showPicker && (
            <div className={`absolute bottom-10 z-30 flex gap-1 p-2 bg-crisp-surface
              border border-crisp-border rounded-2xl shadow-xl animate-popIn
              ${isOwn ? "right-8" : "left-8"}`}>
              {EMOJI_LIST.map((emoji) => {
                const reacted = reactions[emoji]?.includes(currentUser);
                return (
                  <button key={emoji} onClick={() => react(emoji)}
                    className={`w-9 h-9 rounded-xl flex items-center justify-center text-lg
                      transition-all active:scale-90 hover:scale-110
                      ${reacted ? "bg-crisp-accent/20 ring-1 ring-crisp-accent/40" : "hover:bg-crisp-hover"}`}>
                    {emoji}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Reaction pills */}
        {hasReactions && (
          <div className={`flex flex-wrap gap-1 mt-1.5 ${isOwn ? "justify-end" : "justify-start"} px-1`}>
            {Object.entries(reactions).map(([emoji, users]) => {
              if (!users?.length) return null;
              const mine = users.includes(currentUser);
              return (
                <button key={emoji}
                  onClick={() => wsService.sendReaction(msg.id, roomId, emoji)}
                  className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-xs
                    border transition-all active:scale-95 font-mono animate-popIn
                    ${mine
                      ? "bg-crisp-accent/20 border-crisp-accent/40 text-crisp-accent2"
                      : "bg-crisp-card border-crisp-border text-crisp-muted hover:bg-crisp-hover"}`}>
                  <span style={{ fontSize: "13px" }}>{emoji}</span>
                  <span>{users.length}</span>
                </button>
              );
            })}
          </div>
        )}

        <span className="text-[10px] text-crisp-muted font-mono mt-1 px-1">
          {fmtTime(msg.timestamp)}
        </span>
      </div>
    </div>
  );
}

function DateDivider({ label }) {
  return (
    <div className="flex items-center gap-3 my-5">
      <div className="flex-1 h-px bg-crisp-border/60" />
      <span className="text-[11px] text-crisp-muted font-mono px-3 py-1 bg-crisp-card
        border border-crisp-border rounded-full whitespace-nowrap">{label}</span>
      <div className="flex-1 h-px bg-crisp-border/60" />
    </div>
  );
}

function LoadingDots() {
  return (
    <div className="flex justify-center py-10">
      <div className="flex gap-1.5">
        {[0,1,2].map(i => (
          <div key={i} className="w-2 h-2 rounded-full bg-crisp-border2 animate-pulse2"
            style={{ animationDelay: `${i * 0.15}s` }} />
        ))}
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="flex-1 flex flex-col items-center justify-center gap-4 bg-crisp-bg h-full">
      <div className="w-20 h-20 rounded-3xl bg-crisp-surface border border-crisp-border
        flex items-center justify-center">
        <svg className="w-9 h-9 text-crisp-border2" fill="none" viewBox="0 0 24 24"
          stroke="currentColor" strokeWidth={1.5}>
          <path d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8
            a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574
            3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"/>
        </svg>
      </div>
      <div className="text-center px-6">
        <div className="font-display font-bold text-crisp-sub text-lg mb-1">No chat selected</div>
        <div className="font-body text-sm text-crisp-muted leading-relaxed">
          Choose a conversation from the sidebar or start a new one
        </div>
      </div>
    </div>
  );
}

function groupByDate(msgs) {
  const map = {};
  msgs.forEach((m) => {
    const k = fmtDate(m.timestamp) || "Today";
    if (!map[k]) map[k] = [];
    map[k].push(m);
  });
  return Object.entries(map).map(([date, msgs]) => ({ date, msgs }));
}

const SendIcon = () => (
  <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
    <line x1="22" y1="2" x2="11" y2="13"/>
    <polygon points="22 2 15 22 11 13 2 9 22 2"/>
  </svg>
);
